import { createHmac } from "node:crypto"
import { readFileSync } from "node:fs"
import { Cause, Effect, Redacted } from "effect"

interface ReleaseNotice {
  readonly version: string
  readonly downloadUrl: string
}

export const publishRelease = (endpoint: URL, notice: ReleaseNotice) =>
  Effect.gen(function*() {
    const signingKey = yield* Effect.try(() =>
      Redacted.make(readFileSync("/run/secrets/release-signing-key", "utf8").trim())
    )
    const body = JSON.stringify(notice)
    const signature = yield* Effect.try(() =>
      createHmac("sha256", Redacted.value(signingKey)).update(body).digest("hex")
    )
    const response = yield* Effect.tryPromise(() =>
      fetch(endpoint, {
        method: "POST",
        headers: {
          "content-type": "application/json",
          "x-release-signature": signature
        },
        body
      })
    )
    if (!response.ok) {
      return yield* Effect.fail(new Error(`Release endpoint returned ${response.status}`))
    }
    yield* Effect.logInfo(`Published release ${notice.version}`)
  }).pipe(
    Effect.catchCause((cause) => Effect.logError(Cause.pretty(cause)))
  )
